syntax:
Example showcasing potential for RVO:

```c++
MyClass createObject() {
  MyClass obj; 
  // ... initialize obj ...
  return obj; // RVO may eliminate the copy here
}
```

Example where RVO is less likely:

```c++
MyClass createObject() {
  MyClass obj; 
  // ... initialize obj ...
  if (someCondition) return obj;
  else return MyClass(); // RVO unlikely due to conditional return
}
```

code_example:
#include <iostream>
#include <vector>
struct MyClass {
  std::vector<int> data;
  MyClass() { std::cout << "MyClass default constructor called\n"; }
  MyClass(const MyClass& other) { data = other.data; std::cout << "MyClass copy constructor called\n"; }
  MyClass(MyClass&& other) noexcept { data = std::move(other.data); std::cout << "MyClass move constructor called\n"; }
};
MyClass createObject() {
  MyClass obj; 
  obj.data.push_back(1);
  obj.data.push_back(2);
  return obj; 
}
int main() {
  MyClass myObj = createObject();
  return 0;
}
